'use client'

import { Post } from '@/interfaces/post'
import CommentSection from '../comment/commentSection'
import { useState, useRef } from 'react'
import { useAuth } from '@/hooks/useAuth'
import { useUpdatePost, useDeletePost } from '@/hooks/usePosts'
import { useUser } from '@/hooks/useUsers'
import { useGroup } from '@/hooks/useGroups'
import { Button } from '@/components/ui/button'
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu'
import {
  AlertDialog,
  AlertDialogContent,
  AlertDialogHeader,
  AlertDialogFooter,
  AlertDialogCancel,
  AlertDialogAction,
  AlertDialogTitle,
  AlertDialogDescription,
} from '@/components/ui/alert-dialog'
import { MoreHorizontal } from 'lucide-react'
import toast from 'react-hot-toast'
import { cn } from '@/lib/utils'
import { Badge } from '@/components/ui/badge'

export default function PostItemByGroup({ post }: { post: Post }) {
  const { user } = useAuth()
  const updatePost = useUpdatePost()
  const deletePost = useDeletePost()
  const { data: author } = useUser(post.authorId)
  const { data: group } = useGroup(post.techGroupId)

  const [isEditing, setIsEditing] = useState(false)
  const [showDialog, setShowDialog] = useState(false)
  const editableRef = useRef<HTMLDivElement>(null)

  const isAuthor = post.authorId === user?.id

  const handleSave = () => {
    const content = editableRef.current?.innerText || ''
    if (!content.trim()) return

    updatePost.mutate(
      {
        id: post.id,
        data: { content, groupId: post.techGroupId },
      },
      {
        onSuccess: () => {
          toast.success('Post mis à jour ✅')
          setIsEditing(false)
        },
        onError: () => {
          toast.error('Erreur lors de la mise à jour ❌')
        },
      }
    )
  }

  const handleDelete = () => {
    deletePost.mutate(post.id, {
      onSuccess: () => {
        toast.success('Post supprimé 🗑️')
        setShowDialog(false)
      },
      onError: () => {
        toast.error('Erreur lors de la suppression ❌')
      },
    })
  }

  return (
    <div className="bg-green-50 rounded-xl shadow p-4 space-y-2 relative">
      {isAuthor && !isEditing && (
        <div className="absolute top-2 right-2">
          <DropdownMenu>
            <DropdownMenuTrigger asChild>
              <Button variant="ghost" size="icon" className="h-8 w-8">
                <MoreHorizontal className="h-4 w-4" />
              </Button>
            </DropdownMenuTrigger>
            <DropdownMenuContent align="end">
              <DropdownMenuItem onClick={() => setIsEditing(true)}>
                ✏️ Modifier
              </DropdownMenuItem>
              <DropdownMenuItem
                onClick={() => setShowDialog(true)}
                className="text-red-600"
              >
                🗑️ Supprimer
              </DropdownMenuItem>
            </DropdownMenuContent>
          </DropdownMenu>
        </div>
      )}

      <AlertDialog open={showDialog} onOpenChange={setShowDialog}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Supprimer ce post ?</AlertDialogTitle>
            <AlertDialogDescription>
              Cette action est irréversible. Le post sera définitivement supprimé.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Annuler</AlertDialogCancel>
            <AlertDialogAction
              className="bg-red-600 hover:bg-red-700"
              onClick={handleDelete}
            >
              Confirmer
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>

      {/* Auteur */}
      <div className="flex items-center gap-2">
        <div className="bg-blue-100 w-10 h-10 rounded-full flex items-center justify-center font-bold text-sm">
          {author?.username ? author.username.slice(0, 2).toUpperCase() : '??'}
        </div>
        <div>
          <p className="font-semibold">{author?.username}</p>
          <Badge variant="outline" className="text-xs">
            {group?.name || 'Groupe inconnu'}
          </Badge>
        </div>
      </div>

      {/* Contenu éditable */}
      <div
        ref={isEditing ? editableRef : null}
        contentEditable={isEditing}
        suppressContentEditableWarning
        className={cn(
          'text-base p-2',
          isEditing && 'border rounded border-yellow-300 bg-yellow-50'
        )}
      >
        {post.content}
      </div>

      {isAuthor && isEditing && (
        <div className="flex justify-end">
          <Button size="sm" variant="ghost" onClick={handleSave}>
            💾 Enregistrer
          </Button>
        </div>
      )}

      {/* Commentaires */}
      <div className="rounded-xl shadow p-4 bg-white space-y-2">
        <CommentSection postId={post.id} />
      </div>
    </div>
  )
}
